begin;
insert into auth.users (id,email) values ('10000000-0000-4000-8000-000000000001','sv-demo-1@example.com'),('10000000-0000-4000-8000-000000000002','sv-demo-2@example.com'),('10000000-0000-4000-8000-000000000003','sv-demo-3@example.com'),('10000000-0000-4000-8000-000000000004','sv-demo-4@example.com'),('10000000-0000-4000-8000-000000000005','sv-demo-5@example.com'),('10000000-0000-4000-8000-000000000006','sv-demo-6@example.com');
insert into public.clubs (id,name) values ('10000000-0000-4000-8000-000000000010','SV synthetic test'),('10000000-0000-4000-8000-000000000011','Other synthetic club');
insert into public.club_users (club_id,user_id,role,access_status) values ('10000000-0000-4000-8000-000000000010','10000000-0000-4000-8000-000000000001','ADMIN','ACTIVE'),('10000000-0000-4000-8000-000000000010','10000000-0000-4000-8000-000000000002','COACH','ACTIVE'),('10000000-0000-4000-8000-000000000010','10000000-0000-4000-8000-000000000003','ATHLETE','ACTIVE'),('10000000-0000-4000-8000-000000000010','10000000-0000-4000-8000-000000000004','ATHLETE','BLOCKED'),('10000000-0000-4000-8000-000000000011','10000000-0000-4000-8000-000000000006','COACH','ACTIVE');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
do $$
declare c uuid:='10000000-0000-4000-8000-000000000010'; r jsonb; r2 jsonb; a uuid; a2 uuid; d uuid; e uuid; s uuid; sp uuid; sp2 uuid; at uuid; req uuid;
begin
 r:=public.sv_command(c,'CREATE_ATHLETE','{"first_name":"Single","last_name":"Synthetic"}',gen_random_uuid()); a:=(r->>'id')::uuid;
 r:=public.sv_command(c,'CREATE_ATHLETE','{"first_name":"Second","last_name":"Synthetic"}',gen_random_uuid()); a2:=(r->>'id')::uuid;
 r:=public.sv_command(c,'CREATE_DEFINITION','{"discipline":"RUNNING","distance_m":1000,"stroke_code":"NONE","format_code":"INDIVIDUAL","environment_code":"TRACK"}',gen_random_uuid()); d:=(r->>'id')::uuid;
 r:=public.sv_command(c,'CREATE_EVENT',jsonb_build_object('definition_id',d,'title','Single result synthetic'),gen_random_uuid()); e:=(r->>'id')::uuid;
 r:=public.sv_command(c,'CREATE_SESSION',jsonb_build_object('event_id',e,'scheduled_on','2026-10-02','scheduled_at','2026-10-02T08:00:00+05:00','label','Synthetic session'),gen_random_uuid()); s:=(r->>'id')::uuid;
 r:=public.sv_command(c,'REGISTER_PARTICIPANT',jsonb_build_object('session_id',s,'athlete_id',a),gen_random_uuid()); sp:=(r->>'id')::uuid;
 begin perform public.sv_command(c,'PUBLISH_SESSION',jsonb_build_object('id',s,'expected_revision',1),gen_random_uuid()); raise exception 'FAILED: missing time publication'; exception when sqlstate '22023' then null; end;
 req:=gen_random_uuid(); r:=public.sv_command(c,'SAVE_RESULT',jsonb_build_object('session_participant_id',sp,'time_cs',3250),req); at:=(r->>'id')::uuid;
 r2:=public.sv_command(c,'SAVE_RESULT',jsonb_build_object('session_participant_id',sp,'time_cs',3250),req);
 if r<>r2 or (select count(*) from public.attempts where session_participant_id=sp and is_current)<>1 then raise exception 'FAILED: idempotent single result'; end if;
 begin perform public.sv_command(c,'SAVE_RESULT',jsonb_build_object('session_participant_id',sp,'time_cs',3200),gen_random_uuid()); raise exception 'FAILED: second result'; exception when sqlstate '40001' then null; end;
 begin perform public.sv_command(c,'SAVE_ATTEMPT',jsonb_build_object('session_participant_id',sp,'attempt_no',2,'status','FINISHED','time_cs',3200),gen_random_uuid()); raise exception 'FAILED: legacy attempts API'; exception when sqlstate '22023' then null; end;
 perform public.sv_command(c,'SAVE_RESULT',jsonb_build_object('id',at,'expected_revision',1,'time_cs',3300),gen_random_uuid());
 begin perform public.sv_command(c,'SAVE_RESULT',jsonb_build_object('id',at,'expected_revision',1,'time_cs',3200),gen_random_uuid()); raise exception 'FAILED: stale result'; exception when sqlstate '40001' then null; end;
 r:=public.sv_command(c,'REGISTER_PARTICIPANT',jsonb_build_object('session_id',s,'athlete_id',a2),gen_random_uuid());sp2:=(r->>'id')::uuid;
 perform public.sv_command(c,'SAVE_RESULT',jsonb_build_object('session_participant_id',sp2,'time_cs',3300),gen_random_uuid());
 perform public.sv_command(c,'PUBLISH_SESSION',jsonb_build_object('id',s,'expected_revision',1),gen_random_uuid());
 if (select count(*) from public.event_leaderboard where event_id=e and place=1)<>2 then raise exception 'FAILED: equal ranks'; end if;
 perform public.sv_command(c,'CLOSE_EVENT',jsonb_build_object('id',e,'expected_revision',1),gen_random_uuid());
 begin perform public.sv_command(c,'SAVE_RESULT',jsonb_build_object('id',at,'expected_revision',2,'time_cs',3400),gen_random_uuid()); raise exception 'FAILED: missing correction reason'; exception when sqlstate '22023' then null; end;
 perform public.sv_command(c,'SAVE_RESULT',jsonb_build_object('id',at,'expected_revision',2,'time_cs',3400,'reason','Two stopwatch correction'),gen_random_uuid());
 if (select best_time_cs from public.event_leaderboard where event_id=e and athlete_id=a)<>3400 then raise exception 'FAILED: slower correction retains obsolete best'; end if;
 begin perform public.sv_command(c,'REMOVE_PARTICIPANT',jsonb_build_object('id',sp,'expected_revision',1),gen_random_uuid()); raise exception 'FAILED: missing removal reason'; exception when sqlstate '22023' then null; end;
 req:=gen_random_uuid(); r:=public.sv_command(c,'REMOVE_PARTICIPANT',jsonb_build_object('id',sp,'expected_revision',1,'reason','Did not participate'),req);
 r2:=public.sv_command(c,'REMOVE_PARTICIPANT',jsonb_build_object('id',sp,'expected_revision',1,'reason','Did not participate'),req);
 if r<>r2 or exists(select 1 from public.event_leaderboard where event_id=e and athlete_id=a) then raise exception 'FAILED: removal/rank'; end if;
 if not exists(select 1 from public.attempts where id=at and not is_current) then raise exception 'FAILED: history preservation'; end if;
 begin perform public.sv_command(c,'SAVE_RESULT',jsonb_build_object('id',at,'expected_revision',4,'time_cs',3100,'reason','Removed'),gen_random_uuid()); raise exception 'FAILED: removed result edit'; exception when sqlstate '22023' then null; end;
 perform public.sv_command(c,'REOPEN_EVENT',jsonb_build_object('id',e,'expected_revision',2,'reason','More results'),gen_random_uuid());
 r:=public.sv_command(c,'CREATE_SESSION',jsonb_build_object('event_id',e,'scheduled_on','2026-10-02','scheduled_at','2026-10-02T09:00:00+05:00','label','Draft removal'),gen_random_uuid());s:=(r->>'id')::uuid;
 r:=public.sv_command(c,'REGISTER_PARTICIPANT',jsonb_build_object('session_id',s,'athlete_id',a),gen_random_uuid());sp:=(r->>'id')::uuid;
 perform public.sv_command(c,'REMOVE_PARTICIPANT',jsonb_build_object('id',sp,'expected_revision',1),gen_random_uuid());
 begin perform public.sv_command(c,'PUBLISH_SESSION',jsonb_build_object('id',s,'expected_revision',1),gen_random_uuid()); raise exception 'FAILED: all removed publication'; exception when sqlstate '22023' then null; end;
 r:=public.sv_command(c,'REGISTER_PARTICIPANT',jsonb_build_object('session_id',s,'athlete_id',a),gen_random_uuid());
 if (r->>'id')::uuid<>sp or exists(select 1 from public.session_participants where id=sp and removed_at is not null) then raise exception 'FAILED: re-add'; end if;
 perform public.sv_command(c,'SAVE_RESULT',jsonb_build_object('session_participant_id',sp,'time_cs',3500),gen_random_uuid());
 perform public.sv_command(c,'REMOVE_PARTICIPANT',jsonb_build_object('id',sp,'expected_revision',3),gen_random_uuid());
 perform public.sv_command(c,'REGISTER_PARTICIPANT',jsonb_build_object('session_id',s,'athlete_id',a),gen_random_uuid());
 if exists(select 1 from public.attempts where session_participant_id=sp and is_current) then raise exception 'FAILED: re-add old result'; end if;
 perform public.sv_command(c,'SAVE_RESULT',jsonb_build_object('session_participant_id',sp,'time_cs',3600),gen_random_uuid());
 if (select count(*) from public.attempts where session_participant_id=sp)<>2 then raise exception 'FAILED: re-add history'; end if;
 begin perform public.sv_command('10000000-0000-4000-8000-000000000011','REMOVE_PARTICIPANT',jsonb_build_object('id',sp,'expected_revision',5),gen_random_uuid()); raise exception 'FAILED: cross club'; exception when insufficient_privilege then null; end;
end $$;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
do $$ begin
 if exists(select 1 from public.session_participants where removed_at is not null) then raise exception 'FAILED: athlete removed visibility'; end if;
 if exists(select 1 from public.attempts where not is_current) then raise exception 'FAILED: athlete legacy visibility'; end if;
 begin perform public.sv_command('10000000-0000-4000-8000-000000000010','REMOVE_PARTICIPANT','{"id":"10000000-0000-4000-8000-000000000080","expected_revision":1}',gen_random_uuid()); raise exception 'FAILED: athlete write'; exception when insufficient_privilege then null; end;
end $$;
reset role;
select 'Single result, corrections, removal, history, idempotency and role assertions passed' as checks;
rollback;
